const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const pacificPalisades = ee.Geometry.Point([-118.5268, 34.0485]).buffer(5000);
  const date1 = '2025-01-09';
  const date2 = '2025-01-12';

  // 2. Data Acquisition - Sentinel-5P NO2 Tropospheric Column
  function getNO2Collection(date) {
    return ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(pacificPalisades)
      .select('tropospheric_NO2_column_number_density');
  }

  const col1 = getNO2Collection(date1);
  const col2 = getNO2Collection(date2);

  // Check collection sizes
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`${date1} Images: ${size1}`);
  console.log(`${date2} Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Use mean composites and apply QA filtering
  function processCollection(collection) {
    const meanImg = collection.mean();
    // Apply quality filter using the QA band (values > 0.5 are generally good)
    const qa = collection.select('tropospheric_NO2_column_number_density').mean();
    const mask = qa.gt(0.5);
    return meanImg.updateMask(mask);
  }

  const img1 = processCollection(col1);
  const img2 = processCollection(col2);

  // 4. Calculation - Get mean NO2 values
  const reducer = ee.Reducer.mean().setOutputs(['mean']);
  const countReducer = ee.Reducer.count().setOutputs(['count']);

  const stats1 = img1.reduceRegion({
    reducer: reducer.combine(countReducer, '', true),
    geometry: pacificPalisades,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.reduceRegion({
    reducer: reducer.combine(countReducer, '', true),
    geometry: pacificPalisades,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('mean').getInfo();
  const mean2 = stats2.get('mean').getInfo();
  const count1 = stats1.get('count').getInfo();
  const count2 = stats2.get('count').getInfo();

  console.log(`${date1} Mean NO2: ${mean1?.toFixed(6) || 'null'}, Valid Pixels: ${count1}`);
  console.log(`${date2} Mean NO2: ${mean2?.toFixed(6) || 'null'}, Valid Pixels: ${count2}`);

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log('<answer>C2</answer>');
  } else if (mean1 === null || mean2 === null || 
             isNaN(mean1) || isNaN(mean2) ||
             mean1 < 0 || mean2 < 0) { // NO2 values should be non-negative
    console.log('<answer>C3</answer>');
  } else if (mean1 > mean2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
